29	/**
30	 * Names of the proxy environment variables Konnect sync manages.
31	 * On first sync, values are auto-filled from the control plane's `proxy_urls`
32	 * when available; otherwise created as empty strings for manual entry.
33	 *
34	 * - `proxy_host`: host (with port when non-standard), used in http/https/ws/wss URLs.
35	 * - `grpc_proxy_host`: host:port, used in grpc:// URLs.
36	 * - `grpcs_proxy_host`: host:port, used in grpcs:// URLs.
37	 */
38	export const KONNECT_PROXY_VAR_NAMES = ['proxy_host', 'grpc_proxy_host', 'grpcs_proxy_host'] as const;
39	
40	const HTTP_LIKE_PROTOCOLS = new Set(['http', 'https', 'ws', 'wss']);
41	const GRPC_PROTOCOL = 'grpc';
42	const GRPCS_PROTOCOL = 'grpcs';
43	
44	/** Default ports per protocol — used to suppress redundant port numbers in the output. */
45	const DEFAULT_PORTS: Record<string, number> = { http: 80, ws: 80, https: 443, wss: 443 };
46	
47	/** Returns `host` for standard ports, `host:port` for non-standard ones. */
48	function formatHttpLikeHost(host: string, port: number, protocol: string): string {
49	  const defaultPort = DEFAULT_PORTS[protocol];
50	  return defaultPort !== undefined && port === defaultPort ? host : `${host}:${port}`;
51	}
