// Tempered patterns for the "innermost" template tags — content may not contain
// any delimiter, so a match can never span across a nested tag of either kind.
const INNERMOST_VARIABLE = /\{\{(?:(?!\{\{|\{%|\}\}|%\}).)*\}\}/g;
